    int n = vsnprintf(a, a_cap, fmt, ap);
    int m = vsnprintf(b, b_cap, fmt, copy);
    va_end(copy);
    va_end(ap);
    if (n < 0 || m < 0 || n != m ||
        (size_t)n >= a_cap || (size_t)m >= b_cap) return -1;
    return n;
}

static int compare_int(const void *a, const void *b) {
    int x = *(const int *)a, y = *(const int *)b;
