int main(void) {thrd_t t;int value=0,result;if(thrd_create(&t,work,&value)!=thrd_success)return 2;if(thrd_join(t,&result)!=thrd_success)return 3;printf("%d %d\n",value,result);return 0;}

#include <stdio.h>
#include <sys/socket.h>
#include <unistd.h>
int main(void) {int pair[2];if(socketpair(AF_UNIX,SOCK_STREAM,0,pair)<0){perror("socketpair");return 2;}int a=close(pair[0]),b=close(pair[1]);if(a||b)return 3;puts("socketpair available");return 0;}

